if (new GlidePluginManager().isActive('com.sn_hr_core')) {
	var gr = new GlideRecord('sys_schema_attribute_m2m');
	gr.addQuery('schema.name', 'sn_hr_core_coe_security_policy');
	gr.addQuery('schema.element', 'coe');
	gr.addQuery('attribute.name', 'skip_root');
	gr.addQuery('value', 'true');
	gr.query();
	if (gr.next()) {
		gr.setValue('value', 'false');
		gr.update();
	}
}
